function U(id,c,t,o){o=o||{};o.id=id;o.c=c;o.t=t;o.typ=o.typ||'allgemein';KN.push(o);return o}
function L(id,c,t,s,r,m){return U(id,c,t,{s:s,r:r,m:m,light:true})}
function DLG(a){return a.map(function(x,i){return [i%2?'B':'K',x]})}
/* ---------- A Vertriebsgrundlagen ---------- */
U('a1','A','Was bedeutet professioneller Vertrieb?',{s:'Professioneller Vertrieb hilft dem Kunden, eine gute Entscheidung für seine Situation zu treffen. Der Berater versteht zuerst, erklärt dann und respektiert, wenn der Kunde Nein sagt.',w:'Wer Kunden langfristig betreut, lebt von Vertrauen und Empfehlungen. Ein Abschluss, den der Kunde später bereut, kostet mehr als er bringt.',r:['Erst verstehen, dann empfehlen.','Jede Empfehlung mit Gründen und aus der Situation des Kunden begründen.','Ein Nein ernst nehmen und festhalten, nicht bekämpfen.','Beratungs- und Dokumentationspflichten einhalten (§§ 60, 61 VVG).'],st:['Anliegen des Kunden klären.','Situation und Wünsche erfragen.','Passende Möglichkeiten erklären, Nutzen und Grenzen nennen.','Entscheidung dem Kunden überlassen, nächsten Schritt vereinbaren.','Beratung dokumentieren.'],g:'„Ich möchte zuerst verstehen, was Ihnen wichtig ist. Danach zeige ich Ihnen, was dazu passen kann.“',b:'„Das müssen Sie unbedingt haben.“',f:['Produkt vor Bedarf nennen.','Nur über Preis und Leistung sprechen, nicht über die Situation.','Die Dokumentation vernachlässigen.'],m:['Beraten heißt verstehen, erklären, entscheiden lassen.','Ein ehrliches Nein ist ein gutes Ergebnis, wenn es informiert getroffen wurde.'],u:'Beschreibe in zwei Sätzen, wie du dein nächstes Gespräch beginnst, ohne ein Produkt zu nennen.',q:['vv'],typ:'beleg',kw:'vertrieb beratung professionell grundlagen verkaufen'});
U('a2','A','Verkaufen oder Überreden?',{s:'Verkaufen heißt, dem Kunden zu helfen, eine passende Entscheidung zu treffen. Überreden heißt, ihn mit Druck oder Tricks zu einer Entscheidung zu bringen, die er sonst nicht getroffen hätte.',w:'Überredung kann kurzfristig Abschlüsse bringen, gefährdet aber Vertrauen, Bestand und Empfehlungen.',r:['Gründe offenlegen, nicht verschleiern.','Keine künstliche Verknappung und keine Angst als Druckmittel.','Dem Kunden Zeit und Alternativen lassen, auch „nichts tun“.','Nutzen und Grenzen nennen.'],g:'„Das spricht dafür, das spricht dagegen. Was davon ist für Sie wichtig?“',b:'„Das Angebot gilt nur noch heute.“ (wenn es nicht stimmt)',f:['Angst erzeugen („Dann steht Ihre Familie ohne Geld da“).','Einwände übergehen.','Entscheidung erzwingen.'],dia:DLG(['Ich weiß nicht, ob ich das brauche.','Verständlich. Wenn Sie möchten, gehen wir durch, wann das Thema für Sie eine Rolle spielen könnte. Danach entscheiden Sie.','Okay, das hilft.']),m:['Druck ersetzt keine Überzeugung.','Ein Angebot ist eine Einladung, keine Pflicht.'],u:'Formuliere einen Satz, der Zeit lässt, statt zu drängen.',typ:'allgemein',kw:'überreden verkaufen druck manipulation ethik'});
U('a3','A','Wie entsteht Vertrauen?',{s:'Vertrauen entsteht, wenn der Kunde den Berater als fachlich kompetent, wohlwollend und integer erlebt. Das Modell von Mayer, Davis und Schoorman nennt diese drei Faktoren: Fähigkeit, Wohlwollen, Integrität.',w:'Ohne Vertrauen werden Auskünfte zurückgehalten, und Empfehlungen werden angezweifelt.',r:['Fähigkeit: Fachlich sicher und verständlich erklären.','Wohlwollen: Zeigen, dass das Interesse des Kunden zählt, nicht nur der Abschluss.','Integrität: Halten, was man sagt, auch Unangenehmes offen nennen.','Zuverlässigkeit: Zusagen einhalten, pünktlich zurückmelden.'],st:['Zusagen klein halten und einhalten.','Grenzen des eigenen Wissens offen nennen.','Nachteile und Kosten selbst ansprechen.'],f:['Zu viel versprechen.','Fachchinesisch als Kompetenzbeweis.'],m:['Vertrauen wächst durch eingehaltene Zusagen.','Offenheit über Grenzen schafft mehr Vertrauen als Perfektion.'],u:'Welche Zusage kannst du dem Kunden im nächsten Gespräch machen, die du sicher einhältst?',q:['md'],typ:'modell',kw:'vertrauen aufbauen glaubwürdig'});
U('a4','A','Tatsächliche Kundenbedürfnisse erkennen',{s:'Der Kunde nennt oft zuerst ein Produkt oder ein Problem. Das eigentliche Bedürfnis zeigt sich erst durch Nachfragen nach Zielen, Sorgen und Prioritäten.',w:'Wer das Bedürfnis nicht kennt, erklärt am Kunden vorbei.',r:['Offene Fragen vor Lösungen.','Fakten, Wünsche und Vermutungen auseinanderhalten.','Vermutungen durch Rückfragen prüfen.','Prioritäten erfragen statt zu unterstellen.'],st:['Anlass hören.','Nach Zielen und Sorgen fragen.','Zusammenfassen und bestätigen lassen.','Erst dann Lösungen zeigen.'],g:'„Was soll sich für Sie verbessern, wenn wir das regeln?“',b:'„Sie wollen doch bestimmt auch die Familie absichern.“',f:['Zu früh Lösungen nennen.','Das Bedürfnis aus der Lebenslage ableiten, ohne zu fragen.'],m:['Frage, bevor du empfiehlst.','Das Bedürfnis gehört dem Kunden.'],u:'Schreibe drei offene Fragen zu Zielen und Sorgen für ein Gespräch über Vorsorge.',typ:'beleg',q:['mi'],kw:'bedürfnisse bedarf ermitteln analyse'});
L('a5','A','Kundenorientierter Vertrieb','Kundenorientiert beraten heißt, Entscheidungen an Situation, Wünschen und Möglichkeiten des Kunden auszurichten.',['Mit dem Anliegen des Kunden beginnen.','Produkte erst nennen, wenn der Bedarf klar ist.','Alternativen und „Nichtstun“ ehrlich einbeziehen.'],['Der Kunde steht im Mittelpunkt, nicht das Produkt.']);
L('a6','A','Langfristige Kundenbeziehungen aufbauen','Langfristige Beziehungen entstehen durch Verlässlichkeit, Interesse an Veränderungen und regelmäßigen, nützlichen Kontakt.',['Nach jedem Gespräch eine Zusage einhalten.','Anlässe für Kontakt nutzen (Fälligkeit, Lebensereignis).','Nur anrufen, wenn es etwas Nützliches gibt.'],['Beziehung ist ein Konto: Einzahlungen vor Abhebungen.']);
L('a7','A','Geeignete Verkaufsgelegenheiten erkennen','Gelegenheiten ergeben sich aus Anlässen: Vertragsfälligkeit, Lebensereignis, Frage des Kunden, geänderte Situation.',['Auf Anlässe achten, nicht auf Gelegenheiten zum Verkaufen.','Ein Anlass ist eine Einladung zur Frage, kein bestätigter Bedarf.','Das ursprüngliche Anliegen bleibt im Mittelpunkt.'],['Anlass erkennen, Bedarf erfragen, dann anbieten.']);
L('a8','A','Ein Gespräch zielgerichtet führen','Ein Gespräch hat ein Ziel, das der Kunde kennt: Was soll am Ende geklärt sein?',['Agenda zu Beginn nennen.','Ziel und Zeitrahmen abstimmen.','Am Ende prüfen, ob das Ziel erreicht ist.'],['Wer das Ziel nennt, kann das Gespräch führen.']);
L('a9','A','Nutzen statt Produkteigenschaften','Eigenschaften beschreiben das Produkt, Nutzen beschreibt, was es für den Kunden bedeutet. Der Nutzen muss zu seinem Wunsch passen.',['Eigenschaft nennen, Bedeutung für den Kunden erklären.','Nutzen nur nennen, wenn er zur Situation passt.','Keine Garantien, wo keine bestehen.'],['„Das heißt für Sie …“ ist die wichtigste Brücke.']);
L('a10','A','Unterschiedliche Kundentypen','Kunden haben unterschiedliche Informationsbedürfnisse und Entscheidungsstile. Typen sind Hilfen zur Vorbereitung, keine Schubladen.',['Informationsbedarf erfragen: Überblick oder Details?','Tempo des Kunden aufnehmen.','Eindruck durch Verhalten prüfen, nicht festlegen.'],['Anpassen heißt zuhören, nicht einordnen.']);
L('a11','A','Ein professionelles Selbstverständnis','Ein Berater versteht sich als Begleiter bei Entscheidungen, nicht als Verkäufer von Produkten.',['Eigene Rolle klar benennen.','Interessenkonflikte offen ansprechen (Provision, Gesellschaft).','Dokumentieren und Pflichten ernst nehmen.'],['Haltung vor Technik.']);
L('a12','A','Typische Fehler unerfahrener Verkäufer','Häufige Fehler: zu früh Lösungen nennen, zu viel reden, Einwände wegreden, Nutzen nicht übersetzen, nicht abschließen.',['Mehr fragen als erklären.','Pausen aushalten.','Immer einen nächsten Schritt vereinbaren.'],['Fehler erkennt man in der Nachbereitung, nicht im Gespräch.']);
L('a13','A','Authentisch und überzeugend bleiben','Überzeugend wirkt, wer ehrlich, vorbereitet und klar ist. Eingeübte Sätze wirken aufgesetzt, wenn sie nicht zur Person passen.',['Formulierungen in eigenen Worten verwenden.','Unsicherheit offen zugeben.','Zahlen und Fakten vorbereitet haben.'],['Echt vor perfekt.']);
L('a14','A','Mit Ablehnung umgehen','Ablehnung betrifft meist die Situation oder das Angebot, nicht die Person. Eine klare Absage ist hilfreich.',['Nachfragen, ob es um Thema, Zeitpunkt, Preis oder Person geht.','Absage freundlich annehmen und festhalten.','Tür offen lassen, ohne zu drängen.'],['Ein Nein ist eine Information.']);
L('a15','A','Abschlussquote ohne Druck verbessern','Eine bessere Quote entsteht durch bessere Vorbereitung, klarere Bedarfsermittlung und eine klare nächste Frage.',['Gespräche vorbereiten.','Nutzen mit der Situation des Kunden verbinden.','Entscheidung ansprechen und Bedenken klären.'],['Weniger drängen, klarer fragen.']);
L('a16','A','Vertriebsaktivitäten priorisieren','Priorität haben Anlässe mit Termin (Fälligkeiten), bestehende Kontakte mit offenen Fragen und Zusagen.',['Fristen zuerst.','Zusagen vor neuen Aktionen.','Wenige Themen gründlich statt viele oberflächlich.'],['Erst Verbindliches, dann Neues.']);
L('a17','A','Bei schwierigen Gesprächen professionell bleiben','In schwierigen Gesprächen helfen Ruhe, klare Struktur und das Benennen des Anliegens.',['Tief atmen, Tempo reduzieren.','Das Anliegen des Kunden in eigenen Worten wiedergeben.','Erst klären, dann lösen.'],['Ruhe überträgt sich.']);
/* ---------- B Erster Eindruck ---------- */
U('b1','B','Was beeinflusst den ersten Eindruck?',{s:'Menschen bilden sehr schnell einen ersten Eindruck. In Laborstudien genügten schon 100 Millisekunden, um Urteile über Gesichter zu fällen, die stark mit Urteilen ohne Zeitbegrenzung übereinstimmten (Willis & Todorov 2006). Das sagt nichts darüber, ob der Eindruck stimmt.',w:'Der erste Eindruck prägt, wie offen ein Kunde in das Gespräch geht. Er ist aber nicht endgültig: spätere Informationen und Verhalten verändern ihn.',r:['Schnelle Urteile sind belegt, ihre Treffsicherheit ist begrenzt.','In der Studie wurden Gesichter beurteilt, nicht ganze Beratungsgespräche.','Mehr Zeit erhöhte vor allem das Vertrauen in das Urteil und führte zu differenzierteren Eindrücken.','Verhalten im Gespräch (Zuhören, Verlässlichkeit) wirkt länger als der erste Moment.','Spontane Kurzurteile aus Verhaltensausschnitten sagen Ergebnisse besser als Zufall voraus (Ambady & Rosenthal 1992), die Zusammenhänge sind mittelgroß.'],f:['Behauptungen wie „Sie haben 7 Sekunden“ ohne Quelle übernehmen.','Den eigenen Eindruck vom Kunden als Wahrheit nehmen.'],m:['Der erste Eindruck entsteht schnell, ist aber korrigierbar.','Pünktlich, vorbereitet, zugewandt: das beeinflusst die ersten Momente.'],u:'Welche drei Dinge kannst du für die ersten 30 Sekunden beim nächsten Termin konkret vorbereiten?',q:['wt','ar'],typ:'beleg',kw:'erster eindruck wirkung sekunden begrüßung'});
U('b2','B','Fakten statt Vertriebsmythen',{s:'Populäre Zahlen („7 % Worte, 38 % Stimme, 55 % Körpersprache“) stammen aus Experimenten mit widersprüchlichen Botschaften über Gefühle und gelten nicht für Gespräche allgemein (Mehrabian & Wiener 1967).',w:'Wer Mythen weitergibt, verliert fachliche Glaubwürdigkeit und trainiert das Falsche.',r:['Die Mehrabian-Zahlen gelten nur für den Ausdruck von Gefühlen und Einstellungen bei widersprüchlichen Signalen.','Inhalt zählt in Beratungsgesprächen erheblich.','Körpersprache ist keine zuverlässige Gedankenlesehilfe.','Feste Prozent- und Sekundenregeln immer nach der Quelle fragen.'],f:['„Die ersten 7 Sekunden entscheiden alles“ weitergeben.','Gesten als sichere Zeichen deuten.'],m:['Mythen erkennt man an fehlender Quelle und glatten Zahlen.','Wirkung entsteht aus Inhalt, Stimme und Verhalten zusammen.'],u:'Prüfe eine Aussage aus einem Vertriebsratgeber: Welche Quelle wird genannt, welche Einschränkungen gelten?',q:['mw','wt'],typ:'beleg',kw:'mythos mehrabian 7 38 55 körpersprache prozent'});
U('b3','B','Einen Kunden professionell begrüßen',{s:'Eine gute Begrüßung ist freundlich, kurz und greift den Anlass auf. Sie gibt Sicherheit: Der Kunde weiß, was passiert.',w:'Die Begrüßung setzt Ton und Erwartung für das Gespräch.',r:['Aufstehen, Blickkontakt, Namen nennen.','Dank für das Kommen.','Anlass und Ablauf kurz benennen.','Einen Platz anbieten.'],st:['Entgegengehen oder aufstehen.','Name nennen, Hand reichen, wenn passend.','Anlass benennen, Platz anbieten.','Frage zum Einstieg stellen.'],g:'„Guten Morgen, schön, dass Sie da sind. Nehmen Sie gern Platz. Wir schauen uns heute in Ruhe an, welche Möglichkeiten Sie im Hinblick auf die anstehende Fälligkeit haben.“',b:'„Dann legen wir mal los. Also, Sie haben ja einen Vertrag, der ausläuft.“',f:['Zu hektisch starten.','Ohne Anlass beginnen.','Den Namen falsch aussprechen.'],dia:DLG(['Guten Tag, ich habe einen Termin.','Guten Tag, schön, dass Sie da sind. Nehmen Sie gern Platz. Wir schauen heute in Ruhe auf Ihre Fälligkeit. Möchten Sie etwas trinken?']),m:['Gruß, Anlass, Platz, Frage.','Ruhe zu Beginn überträgt sich.'],u:'Formuliere eine Begrüßung für einen Kunden mit Vertragsfälligkeit in zwei Sätzen.',kw:'begrüßung begrüßen kunde empfang'});
U('b4','B','Begrüßungsvarianten für verschiedene Situationen',{s:'Mehrere Varianten helfen, nicht immer dieselben Sätze zu verwenden. Entscheidend ist, dass die Begrüßung zur Beziehung und zum Anlass passt.',w:'Abwechslung wirkt natürlich, Wiederholung aufgesetzt.',r:['Bekannter Kunde: persönlicher, Bezug zum letzten Kontakt.','Neuer Kunde: Name, Rolle, Ablauf, Zeitrahmen.','Zurückhaltender Kunde: ruhiger, weniger Fragen am Anfang.','Gestresster Kunde: Zeitrahmen anbieten, Nutzen nennen.','Mit Bankberater: beide ansprechen, dem Kunden den Mittelpunkt geben.'],g:'Fälligkeit: „Guten Morgen, schön, dass Sie da sind. Wir schauen heute in Ruhe auf Ihre anstehende Fälligkeit.“ Wiederanlage: „Willkommen. Heute geht es um die Frage, wie Ihr Geld weiter für Sie arbeiten kann.“ Bekannt: „Schön, Sie wiederzusehen. Wie war der Urlaub?“ Neu: „Guten Tag, ich bin … von … und begleite Kunden der Bank bei Versicherungsfragen. Wir haben etwa eine halbe Stunde.“',f:['Immer dieselbe Floskel.','Zu lange Vorstellung der eigenen Firma.'],m:['Anlass aufgreifen, Zeitrahmen nennen.','Eine Variante pro Situation bereithalten.'],u:'Schreibe drei Varianten für einen bekannten Kunden mit Vertragsfälligkeit.',kw:'begrüßung varianten fälligkeit wiederanlage bekannt neu'});
L('b5','B','Körpersprache, Mimik und Blickkontakt','Körpersprache wirkt mit, ist aber mehrdeutig. Offene Haltung und angemessener Blickkontakt unterstützen, Gedanken lassen sich daraus nicht sicher ablesen.',['Zugewandte, ruhige Haltung.','Blickkontakt halten, ohne zu starren.','Eindrücke durch Nachfragen prüfen.'],['Körpersprache unterstützt, beweist aber nichts.']);
L('b6','B','Stimme, Sprechtempo und Lautstärke','Eine ruhige, klare Stimme und ein angemessenes Tempo erleichtern das Zuhören. Pausen geben Gewicht.',['Etwas langsamer als gewohnt sprechen.','Wichtiges betonen, danach pausieren.','Lautstärke dem Raum anpassen.'],['Langsam ist verständlich.']);
L('b7','B','Zurückhaltende Kunden','Zurückhaltung kann Schüchternheit, Skepsis oder Vorsicht sein. Ruhe und einfache Fragen helfen.',['Zeit lassen.','Kleine, leichte Einstiegsfragen.','Nicht drängen, Nutzen bildhaft erklären.'],['Zurückhaltung ist kein Desinteresse.']);
L('b8','B','Gestresste oder ungeduldige Kunden','Der Zeitrahmen ist für sie wichtig. Eine kurze Orientierung gibt Sicherheit.',['Zeit erfragen und anbieten, kürzer zu halten.','Das Wichtigste zuerst.','Details nachreichen.'],['Kürze ist Respekt.']);
L('b9','B','Vom Empfang zum Gesprächsplatz','Der Weg zum Platz ist eine Chance für kurzen Kontakt. Der Raum sollte vorbereitet sein.',['Raum, Unterlagen und Getränke vorbereiten.','Sitzposition anbieten, die ein Gespräch auf Augenhöhe erlaubt.','Während des Weges kurzen Small Talk führen oder schweigen, je nach Kunde.'],['Ein vorbereiteter Raum spart Hektik.']);
L('b10','B','Ein natürlicher Gesprächseinstieg','Ein Einstieg wirkt natürlich, wenn er den Anlass aufgreift und offene Fragen stellt.',['Anlass benennen.','Agenda kurz nennen.','Mit offener Frage starten.'],['Anlass, Ablauf, Frage.']);
L('b11','B','Geeigneter Small Talk','Neutrale Themen wie Anreise, Wetter oder Region sind unverfänglich. Persönliches nur, wenn der Kunde es öffnet.',['Kurz halten, nicht ausfragen.','An bekannten Themen anknüpfen.','Keine Politik oder Privates anfassen.'],['Small Talk öffnet die Tür, ersetzt aber nicht das Anliegen.']);
L('b12','B','Wann Small Talk sinnvoll ist','Small Talk passt, wenn Zeit ist und der Kunde mitgeht. Bei Zeitdruck oder ernstem Anlass wird er kurz oder entfällt.',['Auf Signale achten.','Bei Zeitdruck direkt zum Thema.','Nicht erzwingen.'],['Anpassen statt abspulen.']);
L('b13','B','Aufgesetzten oder einstudierten Eindruck vermeiden','Einstudierte Sätze wirken fremd, wenn sie nicht zur Person passen. Hilfreich sind Stichpunkte statt Wortlaut.',['Eigene Worte verwenden.','Auf die Antwort des Kunden reagieren.','Keine Standardfloskeln wiederholen.'],['Zuhören schlägt Skript.']);
L('b14','B','Eine angenehme Gesprächsatmosphäre schaffen','Atmosphäre entsteht durch Ruhe, Aufmerksamkeit und Rahmen: Sitzordnung, Zeit, Getränk, keine Störungen.',['Handy stumm.','Zeitrahmen nennen.','Dem Kunden Raum geben, etwas zu sagen.'],['Ruhe ist ein Angebot.']);
L('b15','B','Kleidung, Ordnung, Pünktlichkeit, Vorbereitung','Diese Faktoren zeigen Wertschätzung. Sie sind Rahmen, ersetzen aber keinen Inhalt.',['Pünktlich oder früher da sein.','Unterlagen sortiert haben.','Kleidung zum Rahmen passend.'],['Vorbereitung ist sichtbar.']);
L('b16','B','Aufmerksamkeit und echtes Interesse zeigen','Aufmerksamkeit zeigt sich durch Blickkontakt, Notizen, Rückfragen und Wiedergabe des Gehörten.',['Nicken allein reicht nicht, wiedergeben.','Notizen ankündigen.','Nicht unterbrechen.'],['Interesse zeigt sich im Nachfragen.']);
L('b17','B','Gesprächspausen','Pausen geben Zeit zum Nachdenken. Wer sie aushält, bekommt oft die wichtigeren Antworten.',['Nach einer Frage warten.','Pause nicht füllen.','Bei langem Schweigen sanft nachfragen.'],['Schweigen ist Denkzeit.']);
L('b18','B','Hektik und Unsicherheit vermeiden','Hektik entsteht durch fehlende Vorbereitung. Ein kurzes Ritual vor dem Termin hilft.',['Unterlagen vorab sortieren.','Atmen vor dem Eintreten.','Langsamer sprechen.'],['Ruhe vorbereiten.']);
L('b19','B','Kommunikationsstil anpassen, ohne unecht zu wirken','Anpassen heißt Tempo, Detailtiefe und Ton an den Kunden anzugleichen, nicht, sich zu verstellen.',['Tempo spiegeln.','Fachsprache dem Kunden anpassen.','Bei sich bleiben.'],['Anpassen ja, verbiegen nein.']);
/* ---------- C Gesprächsführung ---------- */
U('c1','C','Der rote Faden im Gespräch',{s:'Ein Beratungsgespräch folgt einem erkennbaren Ablauf: Begrüßung, Anliegen, Situation, Themen, Besprechung, Entscheidung, Abschluss. Der Kunde sollte wissen, wo er steht.',w:'Struktur gibt Sicherheit und spart Zeit.',r:['Agenda zu Beginn nennen.','Zwischenzusammenfassungen einbauen.','Abschweifungen freundlich zurückholen.'],st:['Einstieg und Anliegen.','Fragen zur Situation.','Überleitung zu Themen.','Besprechung der Angebote.','Fragen und Einwände.','Abschluss und nächste Schritte.'],g:'„Wir haben jetzt Ihr Anliegen geklärt. Als Nächstes würde ich Ihnen gern zwei Themen zeigen, die dazu passen. Ist das in Ordnung?“',b:'Ohne Ankündigung das Thema wechseln.',f:['Kein erkennbares Ziel.','Zu viele Themen.'],m:['Zeigen, wo man im Gespräch steht.','Immer Zusammenfassung vor Themenwechsel.'],u:'Schreibe die sechs Gesprächsabschnitte mit je einem Satz für ein Gespräch über eine Vertragsfälligkeit.',kw:'gesprächsführung struktur roter faden ablauf'});
L('c2','C','Gesprächsvorbereitung','Gute Vorbereitung klärt Anlass, bekannte Fakten, Themen und Fragen, nicht den Wortlaut.',['Anlass und Ziel klären.','Fragen vorbereiten, nicht Antworten.','Unterlagen bereitlegen.'],['Vorbereiten heißt ordnen.']);
L('c3','C','Vertrauensaufbau im Gespräch','Vertrauen wächst durch Zuhören, klare Aussagen und Einhalten von Zusagen im Gespräch selbst.',['Zusagen konkret machen.','Fehler zugeben.','Nicht mehr versprechen, als möglich.'],['Verlässlichkeit zeigt sich im Detail.']);
L('c4','C','Agenda und Zielklärung','Eine kurze Agenda legt Ziel und Reihenfolge fest und macht das Gespräch planbar.',['Ziel in einem Satz nennen.','Reihenfolge und Zeit abstimmen.','Dem Kunden Raum für eigene Punkte geben.'],['Agenda gemeinsam setzen.']);
L('c5','C','Anlass und Erwartungen verstehen','Der Kunde erwartet etwas Bestimmtes. Es lohnt sich, das zu Beginn zu klären.',['Nach Erwartung fragen.','Erwartung zusammenfassen.','Abweichende Themen später anbieten.'],['Erwartung vor Angebot.']);
L('c6','C','Offene und geschlossene Fragen','Offene Fragen laden zum Erzählen ein, geschlossene bestätigen Fakten. Beide haben ihren Platz.',['Offen für Situation und Wünsche.','Geschlossen für Bestätigung.','Nicht mehrere Fragen auf einmal stellen.'],['Offen öffnet, geschlossen sichert.']);
L('c7','C','Fragetechniken im Gespräch','Fragetechniken sind Werkzeuge: offen, vertiefend, verständnisprüfend, priorisierend. Siehe Kategorie D.',['Passende Frage zur Situation wählen.','Eine Frage, dann Pause.','Antworten nutzen.'],['Gute Fragen sind kurz.']);
L('c8','C','Aktives Zuhören im Gespräch','Aktives Zuhören heißt, aufmerksam zu sein und das Gehörte zu bestätigen. Siehe Kategorie E.',['Nicht unterbrechen.','Wiedergeben, was angekommen ist.','Nachfragen bei Unklarheit.'],['Zuhören ist eine Handlung.']);
L('c9','C','Zusammenfassen und Spiegeln','Zusammenfassen sichert Verständnis, Spiegeln zeigt, dass man zugehört hat.',['In eigenen Worten wiedergeben.','Bestätigung abfragen.','Nicht werten.'],['Ist das so richtig?']);
L('c10','C','Vertiefungsfragen','Mit Vertiefungsfragen werden Aussagen konkreter.',['„Können Sie ein Beispiel nennen?“','„Was meinen Sie genau mit …?“','Nicht ausfragen.'],['Konkret statt allgemein.']);
L('c11','C','Umgang mit Gesprächspausen','Pausen sind Denkzeit. Wer sie aushält, erhält überlegtere Antworten.',['Warten.','Nicht antworten für den Kunden.','Danach ruhig nachfragen.'],['Pause ist Arbeit.']);
L('c12','C','Umgang mit Abschweifungen','Abschweifungen zeigen oft, was dem Kunden wichtig ist. Kurz würdigen, dann zurückführen.',['Würdigen, nicht abwürgen.','Thema notieren.','Zum Ablauf zurückkehren.'],['Notieren und zurückkehren.']);
L('c13','C','Themenwechsel und Überleitungen','Themenwechsel brauchen eine Brücke und die Zustimmung des Kunden. Siehe Kategorie H.',['Vorhandenes abschließen.','Brücke formulieren.','Zustimmung einholen.'],['Frage vor Wechsel.']);
L('c14','C','Komplexe Sachverhalte erklären','Komplexes wird verständlich durch kurze Sätze, Bilder und Beispiele. Siehe Kategorie F.',['Eine Idee pro Satz.','Beispiel nennen.','Verständnis prüfen.'],['Einfach heißt nicht falsch.']);
L('c15','C','Nutzenargumentation im Gespräch','Der Nutzen wird dort genannt, wo er zur Aussage des Kunden passt.',['Auf Aussage des Kunden aufbauen.','Konkret bleiben.','Grenzen nennen.'],['Nutzen an Kundenwort binden.']);
L('c16','C','Zwischenzusammenfassungen','Zwischenzusammenfassungen schaffen Orientierung.',['Nach jedem Themenblock.','Kurz.','Bestätigung abfragen.'],['Zusammenfassen vor Weitergehen.']);
L('c17','C','Umgang mit Unsicherheit','Unsicherheit beim Kunden oder bei sich selbst darf benannt werden.',['Unsicherheit ernst nehmen.','Fragen zulassen.','Eigene Wissenslücken offen zugeben.'],['Offenheit entlastet.']);
L('c18','C','Abschluss und nächste Schritte','Ein Gespräch endet mit einem klaren nächsten Schritt. Siehe Kategorie I.',['Zusammenfassen.','Nächsten Schritt festlegen.','Dokumentieren.'],['Nie ohne nächsten Schritt enden.']);
/* ---------- D Fragetechniken und Bedarfsermittlung ---------- */
U('d1','D','Offene Fragen',{s:'Offene Fragen beginnen mit „Was“, „Wie“, „Wann“, „Welche“ und lassen den Kunden in eigenen Worten antworten. Sie liefern Zusammenhänge und Prioritäten.',w:'Wer offen fragt, erfährt mehr über Ziele und Sorgen, als der Kunde zuerst nennen würde.',r:['Eine Frage, dann Pause.','Kurz und ohne Vorannahme formulieren.','„Warum“ vorsichtig verwenden, es kann wie Rechtfertigung klingen.','Auf die Antwort eingehen, nicht sofort die nächste Frage stellen.'],st:['Thema benennen.','Offene Frage stellen.','Pause lassen.','Antwort in eigenen Worten wiedergeben.'],g:'„Was ist Ihnen bei Ihrer Absicherung im Alter wichtig?“',b:'„Sie wollen doch sicher gut abgesichert sein, oder?“',f:['Mehrere Fragen in einer.','Suggestivfragen.','Antwort nicht abwarten.'],dia:DLG(['Was beschäftigt Sie beim Thema Vorsorge am meisten?','Dass es später reicht und ich meinen Kindern nicht zur Last falle.','Verstehe, nicht zur Last fallen ist Ihnen wichtig. Was genau stellen Sie sich darunter vor?']),m:['Offene Fragen öffnen, geschlossene sichern.','Nach der Frage kommt die Stille.'],u:'Formuliere drei offene Fragen zum Thema Pflege, ohne das Wort „Pflegeversicherung“ zu verwenden.',kw:'offene fragen frage was wie fragetechnik'});
U('d2','D','Geschlossene Fragen',{s:'Geschlossene Fragen lassen sich mit Ja, Nein oder einer kurzen Angabe beantworten. Sie sichern Fakten und führen zum Abschluss eines Themas.',w:'Fakten wie Vertragsende oder Familienstand sollten präzise erfragt werden.',r:['Für Fakten und Bestätigungen verwenden.','Nicht als Einstieg in Bedürfnisse.','Nicht als Verhör, einzelne Frage, dann Zuhören.'],g:'„Besteht schon eine Zahnzusatzversicherung?“',b:'„Das ist Ihnen doch zu teuer, oder?“',f:['Zu viele Fragen hintereinander.','Fragen, die die Antwort vorgeben.'],m:['Geschlossen für Fakten, offen für Bedeutung.'],u:'Schreibe drei geschlossene Fragen, mit denen du den Stand der Verträge klärst.',kw:'geschlossene fragen ja nein'});
U('d3','D','Vertiefungsfragen und Verständnisfragen',{s:'Vertiefungsfragen machen Aussagen konkret. Verständnisfragen prüfen, ob man richtig verstanden hat.',w:'Allgemeine Aussagen wie „Ich will Sicherheit“ helfen nur, wenn klar ist, was sie bedeuten.',r:['Auf ein Stichwort des Kunden aufbauen.','Beispiele erfragen.','Verständnis durch Wiedergabe prüfen.'],st:['Stichwort aufgreifen.','„Was genau meinen Sie mit …?“','Beispiel erfragen.','Wiedergeben und bestätigen lassen.'],g:'„Sie sagen, die Zähne sind Ihnen wichtig. Gab es schon einmal eine Rechnung, die Sie überrascht hat?“',b:'„Also Zahnzusatz, richtig?“',f:['Den Begriff selbst deuten.','Zu viel nachbohren.'],dia:DLG(['Ich möchte einfach mehr Sicherheit.','Sicherheit, worauf bezogen?','Wenn ich mal länger krank bin oder jemand pflegen muss.','Verstehe, es geht um den Fall, dass Pflege nötig wird. Habe ich das richtig verstanden?']),m:['Konkret werden hilft beiden.'],u:'Nimm den Kundensatz „Ich möchte nicht, dass es teuer wird“ und schreibe zwei Vertiefungsfragen.',kw:'vertiefungsfragen nachfragen konkret'});
U('d4','D','Bedarfsermittlung',{s:'Bedarf ist die Lücke zwischen Situation, Wunsch und bestehendem Schutz. Er wird gemeinsam mit dem Kunden erarbeitet und nicht unterstellt.',w:'Ohne geklärten Bedarf wird die Beratung zum Produktverkauf, und die Dokumentationspflicht (§ 61 VVG) ist schwer zu erfüllen.',r:['Situation, Wünsche, Bestand, Prioritäten trennen.','Fakten, Wünsche, Vermutungen auseinanderhalten.','Bedarf am Ende zusammenfassen und bestätigen lassen.','Bei fehlenden Angaben nachfragen oder als offen markieren.'],st:['Situation: Wer, Was, Wann?','Bestand: Was besteht bereits?','Wünsche: Was soll sich ändern?','Prioritäten: Was ist am wichtigsten?','Zusammenfassen und bestätigen.'],g:'„Ich fasse zusammen: Ihnen sind die Zähne wichtig, die Brille weniger. Habe ich das richtig verstanden?“',b:'„Das brauchen alle in Ihrem Alter.“',f:['Bedarf aus dem Alter ableiten.','Wünsche des Kunden mit Annahmen vermischen.'],m:['Bedarf wird erfragt, nicht erraten.','Annahmen als Annahmen kennzeichnen.'],u:'Schreibe in vier Zeilen auf, wie du Situation, Bestand, Wünsche und Prioritäten bei einem Kunden erfragst.',q:['vv'],typ:'beleg',kw:'bedarfsermittlung bedarf analyse situation'});
U('d5','D','Prioritäten klären',{s:'Wenn mehrere Themen offen sind, hilft die Frage nach der Reihenfolge: Was ist dem Kunden am wichtigsten, was kann warten?',w:'Zu viele Themen überfordern. Prioritäten verhindern, dass wichtige Punkte untergehen.',r:['Höchstens zwei bis drei Themen pro Gespräch.','Kunde wählt die Reihenfolge.','Übrige Themen mit Termin markieren.'],g:'„Wir haben drei Themen gesammelt. Mit welchem sollen wir heute anfangen?“',b:'„Ich zeige Ihnen mal alles.“',f:['Alles auf einmal besprechen.'],m:['Weniger Themen, bessere Entscheidungen.'],u:'Formuliere eine Priorisierungsfrage für drei Themen.',q:['il','sg'],typ:'beleg',kw:'prioritäten priorisieren reihenfolge themen'});
L('d6','D','Alternativfragen','Alternativfragen bieten zwei konkrete Optionen an, zum Beispiel für Terminfindung oder Themenwahl. Sie sind keine Zwangswahl: „nichts davon“ muss möglich bleiben.',['Optionen ehrlich und gleichwertig nennen.','Nicht bei Entscheidungen über den Bedarf einsetzen.','Auch „keines“ zulassen.'],['Alternativen helfen bei Organisation, nicht beim Bedarf.']);
L('d7','D','Skalierungsfragen','„Wie wichtig ist Ihnen das auf einer Skala von 1 bis 10?“ macht Wichtigkeit sichtbar. Die Nachfrage „Was würde einen Punkt höher bringen?“ klärt Motive.',['Skala kurz erklären.','Nachfragen, nicht bewerten.','Keine Zahl als Zusage werten.'],['Zahl plus Nachfrage.']);
L('d8','D','Hypothetische Fragen','„Angenommen, es käme zu …, was wäre dann wichtig?“ erleichtert es, über Unangenehmes zu sprechen, ohne Angst zu machen.',['Neutral formulieren.','Nicht dramatisieren.','Antworten als Gedankenspiel behandeln.'],['Hypothese ist Einladung, keine Drohung.']);
L('d9','D','Motivfragen','Motivfragen klären, warum etwas wichtig ist: „Was wäre dann für Sie anders?“ Die Antwort zeigt den Nutzen, der zählt.',['Nach dem Wozu fragen.','Antwort in Kundenworten aufgreifen.','Nicht interpretieren.'],['Wozu ist wichtiger als Was.']);
L('d10','D','Fragen zur finanziellen Situation','Finanzielle Fragen sind sensibel. Erst Zweck erklären, dann Rahmen erfragen, und Antworten freiwillig lassen.',['Zweck nennen („Damit ich passende Möglichkeiten zeigen kann“).','Spannen statt Beträge anbieten.','„Möchten Sie dazu etwas sagen?“'],['Zweck erklären, dann fragen.']);
L('d11','D','Fragen zu Familie und Lebenssituation','Lebensumstände beeinflussen Bedarf, sind aber privat. Offen fragen, nicht annehmen.',['Auf Freiwilligkeit achten.','Nicht aus Familienstand ableiten.','Bei Stocken Thema wechseln.'],['Fragen mit Respekt.']);
L('d12','D','Fragen zu bestehenden Verträgen','Bestand erfragen: Welche Verträge, seit wann, wie zufrieden? Kündigung nie vorschlagen, bevor Unterlagen geprüft sind.',['Unterlagen erbitten.','Zufriedenheit erfragen.','Keine voreilige Bewertung fremder Verträge.'],['Erst prüfen, dann raten.']);
L('d13','D','Fragen zu Zielen und Wünschen','Ziele sind konkret, wenn Zeit und Zweck genannt werden: „Bis wann? Wofür?“',['Zeithorizont erfragen.','Zweck erfragen.','Realistische Erwartungen klären.'],['Ziel braucht Zeit und Zweck.']);
L('d14','D','Fragen zu Sorgen und Bedenken','Sorgen ernst nehmen, nicht ausräumen. Sie zeigen oft den eigentlichen Anlass.',['Nachfragen statt beruhigen.','Sorgen wiedergeben.','Keine Angst verstärken.'],['Sorge hören, dann klären.']);
L('d15','D','Fragen zur Entscheidungssituation','Wer entscheidet mit? Bis wann? Was fehlt noch? So wird der Weg zur Entscheidung sichtbar.',['Mitentscheider einbeziehen.','Zeitplan erfragen.','Fehlende Informationen klären.'],['Entscheidungsweg erfragen.']);
L('d16','D','Zu viele Fragen vermeiden','Fragen in Serie wirken wie ein Verhör. Zwischen den Fragen zusammenfassen und Raum geben.',['Nach zwei bis drei Fragen zusammenfassen.','Unnötiges weglassen.','Vorab klären, wofür die Fragen sind.'],['Wenig fragen, gut zuhören.']);
L('d17','D','Fragen anpassen, wenn Kunden schweigsam sind','Schweigsame Kunden brauchen kleine Einstiege: Wahlfragen, Beispiele, Zeit.',['Leichte Fragen zuerst.','Beispiele anbieten.','Ruhe aushalten.'],['Einfach beginnen.']);
/* ---------- E Aktives Zuhören ---------- */
U('e1','E','Aktives Zuhören',{s:'Aktives Zuhören heißt, aufmerksam zuzuhören, das Gehörte in eigenen Worten wiederzugeben und nachzufragen. Das Konzept geht auf Rogers und Farson (1957) zurück.',w:'Kunden öffnen sich eher, wenn sie sich verstanden fühlen. Fehlverständnisse werden früh erkannt.',r:['Nicht unterbrechen.','Gehörtes wiedergeben, nicht bewerten.','Gefühle ernst nehmen.','Gedanken zurückstellen, bis der Kunde fertig ist.'],st:['Blickkontakt, ruhige Haltung.','Ausreden lassen.','Mit eigenen Worten wiedergeben.','Auf Richtigkeit prüfen.','Nachfragen.'],g:'„Sie sagen, Sie möchten sich nicht zu lange binden, aber trotzdem gut abgesichert sein. Stimmt das so?“',b:'Zustimmend nicken und während des Zuhörens die nächste Antwort planen.',f:['Zu schnell Lösungen anbieten.','Ins Wort fallen.','Auf dem Handy nachsehen.'],dia:DLG(['Ich habe ein bisschen Angst, dass ich später Pflege brauche und alles weg ist.','Sie machen sich Sorgen, dass Pflege Ihr Vermögen aufbraucht. Habe ich das richtig verstanden?','Ja, genau. Meine Mutter hat das erlebt.','Das klingt belastend. Wollen wir schauen, was das konkret für Sie bedeuten kann?']),m:['Wiedergeben ist wichtiger als Zustimmen.','Verstanden fühlen kommt vor überzeugt sein.'],u:'Gib in zwei Sätzen wieder: „Ich weiß nicht, ob ich das alles brauche, es ist so viel.“',q:['rf'],typ:'beleg',kw:'aktives zuhören zuhören paraphrasieren'});
U('e2','E','Paraphrasieren und Zusammenfassen',{s:'Paraphrasieren heißt, in eigenen Worten wiederzugeben, was der Kunde gesagt hat. Zusammenfassen bündelt mehrere Aussagen.',w:'Der Kunde kann korrigieren, bevor ein Missverständnis zur Fehlberatung wird.',r:['Eigene Worte, nicht Papageien.','Kurz bleiben.','Mit Bestätigungsfrage enden.','Keine Bewertung einbauen.'],g:'„Wenn ich Sie richtig verstehe, ist Ihnen wichtig, dass die Beiträge im Alter nicht steigen. Stimmt das?“',b:'„Also wollen Sie das Günstigste.“',f:['Die eigene Deutung als Aussage des Kunden ausgeben.'],m:['Wiedergeben, nicht deuten.','Bestätigung einholen.'],u:'Fasse einen längeren Kundensatz in zwei Zeilen zusammen.',q:['rf'],typ:'beleg',kw:'paraphrasieren zusammenfassen spiegeln wiedergeben'});
U('e3','E','Vermutungen prüfen',{s:'Wir ziehen beim Zuhören Schlüsse. Diese Vermutungen sollten wir als Frage formulieren, bevor wir sie als Tatsache behandeln.',w:'Falsche Annahmen führen zu Beratung am Kunden vorbei.',r:['Vermutung als Frage formulieren.','Fakten und Deutung trennen.','Korrektur annehmen.'],g:'„Ich habe den Eindruck, dass Ihnen der Beitrag wichtiger ist als der Leistungsumfang. Stimmt das?“',b:'„Sie schauen ja nur auf den Preis.“',f:['Vermutung als Wahrheit behandeln.'],m:['Annahme als Frage, nicht als Aussage.'],u:'Formuliere eine Vermutung zu einem schweigsamen Kunden als Frage.',kw:'vermutungen annahmen prüfen interpretieren'});
L('e4','E','Schweigen und Pausen aushalten','Schweigen kann Nachdenken bedeuten. Eine kurze Pause erhöht oft die Qualität der Antwort.',['Zählen bis fünf.','Freundlich bleiben.','Nach der Pause nachfragen.'],['Pause ist Zuhören.']);
L('e5','E','Gefühle erkennen und ansprechen','Gefühle benennen („Das klingt, als würde Sie das belasten“) zeigt Verständnis, ohne zu bewerten.',['Vorsichtig formulieren.','Nicht psychologisieren.','Korrektur zulassen.'],['Gefühl benennen, nicht deuten.']);
L('e6','E','Nonverbale Signale richtig einordnen','Signale sind Hinweise, keine Beweise. Bei Auffälligkeiten nachfragen.',['Veränderungen beobachten.','Fragen statt deuten.','Nicht aus einzelnen Gesten schließen.'],['Beobachten, fragen, bestätigen.']);
L('e7','E','Typische Zuhörfehler','Fehler: unterbrechen, Ratschläge geben, abschweifen, planen, was man als Nächstes sagt.',['Notizen statt Planen.','Auf Pausen warten.','Handy weg.'],['Zuhören braucht Aufmerksamkeit.']);
L('e8','E','Zuhören in Telefonaten','Am Telefon fehlt Mimik. Kürzere Zusammenfassungen und mehr Bestätigung helfen.',['Zusammenfassungen häufiger.','Ruhig sprechen.','Geräusche vermeiden.'],['Am Telefon öfter bestätigen.']);
L('e9','E','Zuhören bei mehreren Gesprächsteilnehmern','Alle ansprechen, Namen nutzen, Entscheider erkennen, ohne andere auszugrenzen.',['Reihum fragen.','Blickkontakt verteilen.','Zusammenfassen für alle.'],['Alle gehören ins Gespräch.']);
/* ---------- F Nutzen und Erklären ---------- */
U('f1','F','Nutzen verständlich erklären',{s:'Nutzen heißt: Was bedeutet diese Leistung für die Situation des Kunden? Die Brücke ist „Das heißt für Sie …“.',w:'Ohne Übersetzung bleiben Leistungsmerkmale abstrakt.',r:['Erst Merkmal, dann Nutzen, dann Bezug zum Kunden.','Keine Garantie, wo keine besteht.','Grenzen nennen.','Beispiel nutzen.'],st:['Wunsch des Kunden aufgreifen.','Merkmal nennen.','„Das heißt für Sie …“','Prüfen, ob es passt.'],g:'„Sie sagten, Zahnersatz soll Sie nicht überraschen. Dieser Tarif übernimmt einen Teil der Kosten über die Kasse hinaus. Das heißt: Sie wissen vorher besser, womit Sie rechnen.“',b:'„Das ist der beste Tarif am Markt.“',f:['Superlative.','Fachbegriffe ohne Erklärung.'],m:['Merkmal, Nutzen, Bezug.','Nutzen ist, was der Kunde so sieht.'],u:'Übersetze „erstattet 80 Prozent bei Zahnersatz“ in einen Nutzensatz für einen Kunden, der Sorge vor hohen Rechnungen hat.',kw:'nutzen argumentation vorteil erklären'});
U('f2','F','Komplexes einfach erklären',{s:'Einfach erklären heißt, auf das Wesentliche zu reduzieren und ein Bild oder Beispiel zu nutzen. Nicht vereinfachen bis es falsch wird.',w:'Wer nicht versteht, entscheidet nicht oder entscheidet falsch.',r:['Ein Gedanke pro Satz.','Fachbegriff erklären oder ersetzen.','Beispiel statt Definition.','Verständnis prüfen.'],g:'„Die Kasse zahlt einen festen Zuschuss, die Zusatzversicherung deckt einen Teil des Restbetrags.“',b:'„Das läuft über Festzuschüsse nach § 55 SGB V mit Staffelung.“',f:['Zu viel Detail.','Die Rückfrage vergessen.'],m:['Einfach, aber richtig.','Nach dem Erklären fragen: Ist das verständlich?'],u:'Erkläre in zwei Sätzen den Unterschied zwischen gesetzlicher Leistung und Zusatzversicherung.',kw:'einfach erklären verständlich fachbegriffe'});
L('f3','F','Beispiele und Vergleiche','Beispiele machen Abstraktes greifbar. Sie müssen fiktiv oder verallgemeinert sein, nie echte Kunden.',['Alltagsbeispiele.','Passend zur Situation.','Nicht als Beweis darstellen.'],['Ein Beispiel ersetzt keine Begründung.']);
L('f4','F','Zahlen verständlich darstellen','Zahlen brauchen Bezug: pro Monat, pro Jahr, im Vergleich. Rundung und Annahmen offenlegen.',['Einheit nennen.','Vergleichswert zeigen.','Annahmen sagen.'],['Zahl mit Bezug.']);
L('f5','F','Vorteile und Grenzen offen darstellen','Wer Grenzen nennt, wird glaubwürdiger. Wartezeiten, Ausschlüsse und Kosten gehören dazu.',['Vorteile und Grenzen gleich gewichten.','Nicht verstecken.','Auf Unterlagen verweisen.'],['Grenzen schaffen Vertrauen.']);
L('f6','F','Fachbegriffe vermeiden oder erklären','Jeder Fachbegriff braucht eine Erklärung in Alltagssprache.',['Begriff in einem Satz erklären.','Nicht belehren.','Nachfragen, was bekannt ist.'],['Erst Wort, dann Übersetzung.']);
L('f7','F','Verständnis prüfen','Fragen wie „Wie würden Sie das in eigenen Worten sagen?“ prüfen Verständnis, ohne zu testen.',['Eigene Unklarheit zugeben.','Nicht abfragen.','Nachfassen bei Zögern.'],['Prüfen heißt anbieten, nicht abfragen.']);
L('f8','F','Struktur beim Erklären','Struktur: erst das Ziel, dann der Weg, dann die Zusammenfassung.',['Ankündigung.','Drei Punkte maximal.','Zusammenfassen.'],['Ankündigen, erklären, zusammenfassen.']);
L('f9','F','Visualisierung und Unterlagen nutzen','Skizzen, Grafiken und Angebote helfen. Sie sollten das Gespräch unterstützen, nicht ersetzen.',['Eine Seite pro Thema.','Mit Kunden zusammen ansehen.','Notizen auf dem Blatt.'],['Papier unterstützt, ersetzt nicht.']);
/* ---------- G Einwandbehandlung (13) ---------- */
function EW(id,t,e,o){o.e=e;o.typ='einwand';o.ew=true;o.kw=(o.kw||'')+' einwand '+e.toLowerCase();return U(id,'G',t,o)}
EW('g1','„Das ist mir zu teuer“','Das ist mir zu teuer.',{bed:'Der Beitrag passt nicht ins Budget, der Nutzen ist nicht klar, oder der Kunde vergleicht mit einer anderen Zahl.',nv:'Nicht sofort mit Rabatt oder Argumenten reagieren. Teuer gegenüber was?',rf:'„Was ist für Sie der Maßstab, an dem der Beitrag gemessen wird?“ oder „Welchen Betrag hätten Sie sich vorgestellt?“',aw:'„Verstehe. Dann schauen wir, welche Leistung Ihnen wichtig ist und was davon sich im Budget lösen lässt. Manchmal ist ein kleinerer Umfang besser als gar kein Schutz.“',d:['Das ist mir zu teuer.','Verstehe. Teuer im Vergleich wozu? Haben Sie eine Zahl im Kopf?','Ich dachte an etwa die Hälfte.','Dann schauen wir, welche Leistungen Ihnen wichtig sind und was man ohne große Lücke weglassen könnte.'],fe:'Sofort den Preis rechtfertigen oder Rabatt anbieten.',lp:'Preis ist ein Vergleich. Erst klären, womit.'});
EW('g2','„Ich habe schon eine Versicherung“','Ich habe schon eine Versicherung.',{bed:'Der Kunde fühlt sich versorgt, oder er möchte nicht wechseln, oder er kennt den Umfang seines Schutzes nicht.',nv:'Nicht den bestehenden Vertrag schlechtmachen.',rf:'„Welche Leistungen haben Sie dort, und wie zufrieden sind Sie damit?“',aw:'„Das ist gut. Wenn Sie möchten, schauen wir gemeinsam in die Unterlagen, was abgedeckt ist und was nicht. Danach entscheiden Sie, ob etwas geändert werden sollte. Ein Wechsel ist keine Pflicht.“',d:['Ich habe schon eine Versicherung.','Das ist gut. Wissen Sie, welche Leistungen darin enthalten sind?','Nicht genau.','Dann schauen wir kurz drauf, ohne dass Sie etwas ändern müssen. Haben Sie die Unterlagen dabei?'],fe:'Den bestehenden Vertrag abwerten.',lp:'Bestand prüfen, nicht angreifen.'});
EW('g3','„Ich muss das erst mit meinem Partner besprechen“','Ich muss das erst mit meinem Partner besprechen.',{bed:'Es ist eine gemeinsame Entscheidung, oder der Kunde braucht Zeit, oder es ist ein höflicher Ausweg.',nv:'Nicht vermuten, dass es ein Vorwand ist.',rf:'„Was wäre dem Partner dabei wichtig?“ oder „Wollen wir einen Termin zu zweit vereinbaren?“',aw:'„Das verstehe ich, es ist ja eine gemeinsame Entscheidung. Ich fasse Ihnen die wichtigsten Punkte kurz zusammen, und wir können gern einen Termin zu zweit machen.“',d:['Ich muss das mit meinem Partner besprechen.','Das ist verständlich. Was wäre Ihrem Partner dabei wichtig?','Vor allem die Kosten.','Dann gebe ich Ihnen die Beitragsübersicht mit. Wollen wir einen Termin zu zweit festhalten?'],fe:'Drängen oder den Partner infrage stellen.',lp:'Mitentscheider einbeziehen.'});
EW('g4','„Dafür habe ich gerade keine Zeit“','Dafür habe ich gerade keine Zeit.',{bed:'Der Termin ist ungünstig, das Thema hat keine Priorität, oder der Kunde ist überfordert.',nv:'Nicht auf Zeitgewinn pochen.',rf:'„Wann würde es besser passen?“ oder „Wollen wir uns auf das Wichtigste beschränken?“',aw:'„Verstehe. Ich kann es auf fünf Minuten kürzen oder wir verschieben auf einen Termin, der besser passt. Was ist Ihnen lieber?“',d:['Dafür habe ich jetzt keine Zeit.','Verstehe. Möchten Sie eine Kurzfassung oder lieber einen anderen Termin?','Lieber später.','Gern. Passt Ihnen nächste Woche eher vormittags oder nachmittags?'],fe:'Weiterreden oder Dringlichkeit herstellen.',lp:'Zeit respektieren, Alternative anbieten.'});
EW('g5','„Ich überlege es mir und melde mich“','Ich überlege es mir und melde mich.',{bed:'Es fehlen Informationen, der Kunde hat unausgesprochene Bedenken, oder er möchte das Gespräch freundlich beenden.',nv:'Nicht annehmen, dass es ein Nein ist.',rf:'„Was würde Ihnen bei der Entscheidung helfen?“ oder „Gibt es einen Punkt, der noch offen ist?“',aw:'„Gern. Damit ich Ihnen nachher nichts schuldig bleibe: Gibt es eine Frage, die ich noch klären sollte? Und wenn Sie möchten, melde ich mich in einer Woche bei Ihnen.“',d:['Ich überlege es mir und melde mich.','Gern. Was würde Ihnen bei der Entscheidung helfen?','Ich bin mir bei den Kosten unsicher.','Dann gebe ich Ihnen eine Übersicht dazu mit. Soll ich in einer Woche nachfragen?'],fe:'Hinterherlaufen oder nichts vereinbaren.',lp:'Nächsten Schritt vereinbaren, ohne zu drängen.'});
EW('g6','„Meine Bank macht das doch alles“','Meine Bank macht das doch alles.',{bed:'Der Kunde vertraut der Bank und sieht keinen Unterschied zwischen Bank und Versicherung.',nv:'Nicht die Bank abwerten.',rf:'„Was macht Ihre Bank für Sie im Versicherungsbereich?“',aw:'„Die Bank ist Ihr Ansprechpartner für Geldanlage und Finanzierung. Für Versicherungen arbeitet sie mit uns zusammen. Wir schauen jetzt gemeinsam nur auf den Versicherungsteil.“',d:['Meine Bank macht das doch alles.','Mit der Bank arbeiten wir eng zusammen. Was haben Sie dort schon für Versicherungen?','Eigentlich nichts.','Dann zeige ich Ihnen, was zu Ihrer Situation passen kann.'],fe:'Die Bank herabsetzen.',lp:'Zusammenarbeit ehrlich erklären.'});
EW('g7','„Ich brauche das nicht, die gesetzliche Absicherung reicht“','Ich brauche das nicht, die gesetzliche Rente reicht.',{bed:'Der Kunde kennt Lücken nicht, oder er hat andere Prioritäten, oder er möchte sich nicht damit befassen.',nv:'Nicht widerlegen, sondern zeigen, was die gesetzliche Leistung abdeckt.',rf:'„Was erwarten Sie von der gesetzlichen Leistung im Ernstfall?“',aw:'„Das kann sein. Die gesetzliche Absicherung ist eine Grundlage. Ob eine Lücke bleibt, hängt von Ihrem Leben ab. Wollen wir kurz prüfen, wie hoch die Lücke im Ernstfall sein könnte?“',d:['Die gesetzliche Absicherung reicht mir.','Das ist eine gute Grundlage. Was erwarten Sie davon im Ernstfall?','Dass das meiste bezahlt wird.','Dann schauen wir kurz, was die gesetzliche Leistung wirklich übernimmt und wo ein Eigenanteil bleibt.'],fe:'Angst machen oder Zahlen ohne Quelle nennen.',lp:'Lücke zeigen, nicht behaupten.'});
EW('g8','„Ich möchte erst Angebote von anderen vergleichen“','Ich möchte erst Angebote von anderen vergleichen.',{bed:'Der Kunde will eine gute Entscheidung treffen. Das ist vernünftig.',nv:'Nicht als Ablehnung werten.',rf:'„Worauf werden Sie beim Vergleich besonders achten?“',aw:'„Sehr gut, vergleichen lohnt sich. Ich gebe Ihnen eine Übersicht mit den wichtigsten Leistungen mit, damit Sie gleiche Dinge vergleichen. Sollen wir in einer Woche darüber sprechen?“',d:['Ich möchte erst vergleichen.','Gute Idee. Worauf achten Sie dabei am meisten?','Auf den Preis und die Leistungen bei Zahn.','Dann gebe ich Ihnen die Leistungsübersicht mit. Wollen wir in einer Woche darauf schauen?'],fe:'Vergleich verhindern oder Druck aufbauen.',lp:'Vergleichen ist ein Zeichen von Interesse.'});
EW('g9','„Ich brauche das nicht“','Ich brauche das nicht.',{bed:'Der Kunde sieht keinen Nutzen, hat das Thema nicht auf dem Schirm, oder hat es bereits anders geregelt.',nv:'Nicht argumentieren, ob er es braucht.',rf:'„Was spricht für Sie dagegen?“ oder „Wie haben Sie das bisher geregelt?“',aw:'„Das kann sein. Ich möchte Ihnen nichts verkaufen, was Sie nicht brauchen. Darf ich Ihnen kurz zeigen, in welchen Situationen es relevant wird? Danach entscheiden Sie.“',d:['Ich brauche das nicht.','Okay. Wie haben Sie das Thema bisher geregelt?','Gar nicht, passiert ja nichts.','Verstehe. Darf ich zwei Situationen zeigen, in denen es eine Rolle spielen kann? Danach ist es Ihre Entscheidung.'],fe:'Dem Kunden widersprechen.',lp:'Erst klären, dann zeigen.'});
EW('g10','„Mir passiert schon nichts“','Mir passiert schon nichts, ich bin gesund.',{bed:'Der Kunde sieht kein Risiko, oder er möchte nicht daran denken.',nv:'Nicht mit Schreckensbildern reagieren.',rf:'„Was würde passieren, wenn doch etwas wäre?“',aw:'„Das hoffe ich für Sie. Versicherung ist für den Fall gedacht, den man nicht plant. Wir können kurz schauen, wie hoch eine Rechnung im Ernstfall wäre, dann können Sie entscheiden, ob das Risiko für Sie tragbar ist.“',d:['Mir passiert schon nichts.','Das wünsche ich Ihnen. Wie würden Sie eine größere Rechnung stemmen, wenn doch?','Aus Ersparnissen.','Dann schauen wir, wie groß so eine Rechnung sein könnte und ob das passt.'],fe:'Angst erzeugen.',lp:'Risiko nüchtern darstellen.'});
EW('g11','„Ich will mich nicht lange binden“','Ich will mich nicht lange binden.',{bed:'Der Kunde befürchtet Unflexibilität oder hat schlechte Erfahrungen mit Laufzeiten.',nv:'Nicht Bindung kleinreden.',rf:'„Was genau macht Ihnen an der Bindung Sorge?“',aw:'„Verstehe. Laufzeit und Kündigungsfrist stehen im Angebot, wir schauen sie zusammen an. Dann sehen Sie, was für Sie passt.“',d:['Ich will mich nicht lange binden.','Verstehe. Was ist Ihre Sorge dabei?','Dass ich nicht rauskomme, wenn es nicht passt.','Dann zeige ich Ihnen die Laufzeit und die Kündigungsfrist genau.'],fe:'Bedingungen verschweigen.',lp:'Bedingungen offen zeigen.'});
EW('g12','„Im Internet ist es günstiger“','Im Internet ist es günstiger.',{bed:'Der Kunde sieht Preisunterschiede, kennt aber Leistungsunterschiede nicht.',nv:'Nicht das Internet schlechtreden.',rf:'„Welche Leistungen waren in dem Angebot enthalten?“',aw:'„Das kann sein. Wichtig ist, dass wir Gleiches mit Gleichem vergleichen. Haben Sie das Angebot zur Hand? Dann schauen wir gemeinsam, ob Leistung und Bedingungen übereinstimmen.“',d:['Im Internet ist es günstiger.','Kann sein. Haben Sie die Leistungen verglichen?','Nur den Preis.','Dann schauen wir die Unterschiede an, damit der Preis vergleichbar wird.'],fe:'Pauschal schlechtreden.',lp:'Preis ist nur ein Merkmal.'});
EW('g13','„Ich habe schlechte Erfahrungen gemacht“','Ich habe schlechte Erfahrungen mit Versicherungen gemacht.',{bed:'Der Kunde hatte einen Streit oder Ärger. Das Vertrauen ist beschädigt.',nv:'Nicht rechtfertigen oder Branche verteidigen.',rf:'„Was ist damals passiert?“',aw:'„Das tut mir leid zu hören. Erzählen Sie gern, was passiert ist. Dann kann ich besser einschätzen, worauf Sie jetzt besonders achten sollten.“',d:['Ich habe schlechte Erfahrungen gemacht.','Das tut mir leid. Möchten Sie erzählen, was passiert ist?','Ein Schaden wurde nicht anerkannt.','Danke fürs Erzählen. Wir können heute besonders darauf achten, was im Schadenfall gilt.'],fe:'Verteidigen oder bagatellisieren.',lp:'Erst zuhören, dann einordnen.'});
/* ---------- H Überleitungen ---------- */
U('h1','H','Von einem Anliegen zum nächsten Thema',{s:'Eine Überleitung verbindet das erledigte Thema mit dem nächsten und holt die Zustimmung des Kunden ein.',w:'Ohne Überleitung wirkt ein Themenwechsel wie ein Verkaufstrick.',r:['Thema abschließen.','Brücke bauen: Bezug zur Situation oder zum Anlass.','Zustimmung erfragen.','Nein akzeptieren.'],st:['Zusammenfassen.','Brücke formulieren.','Fragen, ob der Kunde das Thema möchte.','Kurz und konkret vorstellen.'],g:'„Wir haben jetzt Ihre Hausrat geklärt. Wenn Sie möchten, schauen wir noch, ob es beim Thema Zahnreinigung etwas gibt, das für Sie relevant wäre. Ist das in Ordnung?“',b:'„Und dann habe ich noch was für Sie.“',f:['Zu schnell.','Ohne Bezug.','Nein nicht beachten.'],dia:DLG(['Damit wären wir mit der Hausrat durch.','Genau. Sie hatten vorhin erwähnt, dass bei der Brille Kosten anfielen. Wollen wir kurz schauen, ob es dazu etwas gibt?','Kurz gern.']),m:['Brücke und Frage vor dem Wechsel.'],u:'Formuliere eine Überleitung vom Thema Hausrat zur Frage nach Gesundheitsleistungen.',kw:'überleitung übergang themenwechsel zusatzangebot'});
U('h2','H','Zusatzangebote ohne Aufdringlichkeit',{s:'Zusatzangebote sind sinnvoll, wenn sie einen Bezug zum Anliegen oder zur Situation haben. Sie werden als Möglichkeit angeboten, nicht als Pflicht.',w:'Aufdringlichkeit kostet Vertrauen. Eine ehrliche Einladung wird eher angenommen.',r:['Bezug zum Anlass herstellen.','Höchstens ein bis zwei Themen.','Nutzen kurz benennen.','Nein akzeptieren und festhalten.'],g:'„Mir ist aufgefallen, dass wir noch nicht über Pflege gesprochen haben. Möchten Sie dazu kurz einen Überblick?“',b:'„Das müssen Sie auch noch absichern.“',f:['Zu viele Zusatzthemen.','Bedarf unterstellen.'],m:['Anbieten, nicht aufdrängen.','Ein Nein ist ein Ergebnis.'],u:'Schreibe einen Satz, mit dem du Pflege anbietest, ohne Bedarf zu unterstellen.',kw:'zusatzangebote cross-selling aufdringlich'});
L('h3','H','Bedarf für ein weiteres Thema erkennen','Anzeichen: Kunde nennt Lebensereignis, fragt nach, oder erwähnt Lücken. Nicht jeder Hinweis ist ein Bedarf: nachfragen.',['Hinweise sammeln.','Nachfragen.','Nicht überinterpretieren.'],['Hinweis ist kein Bedarf.']);
L('h4','H','Kundennutzen beim Zusatzthema','Beim Zusatzthema zählt der Bezug: Warum jetzt, warum für diesen Kunden?',['Bezug nennen.','Konkret bleiben.','Optionen zeigen.'],['Warum jetzt? Warum Sie?']);
L('h5','H','Geeigneter Zeitpunkt für Zusatzthemen','Nach Abschluss eines Themas und bei positiver Stimmung. Nicht bei Zeitdruck oder Verärgerung.',['Auf Signale achten.','Zeit prüfen.','Termin vorschlagen statt jetzt drängen.'],['Timing vor Inhalt.']);
L('h6','H','Absagen akzeptieren','Eine Absage wird freundlich angenommen und festgehalten. So bleibt die Tür offen.',['Danken.','Notieren.','Später nur bei Anlass wieder ansprechen.'],['Absage achten.']);
L('h7','H','Folgetermin für zusätzliche Themen','Zusatzthemen lassen sich mit eigenem Termin besser besprechen.',['Termin anbieten.','Unterlagen mitgeben.','Erinnerung setzen.'],['Eigenes Thema, eigener Termin.']);
/* ---------- I Abschluss ---------- */
U('i1','I','Das Gespräch sauber abschließen',{s:'Ein guter Abschluss fasst zusammen, klärt die Entscheidung und legt den nächsten Schritt fest.',w:'Ohne Abschluss verpufft die Beratung. Zusagen und Aufgaben gehen verloren.',r:['Zusammenfassen: Was haben wir besprochen?','Entscheidung ansprechen: Was ist Ihre Einschätzung?','Nächsten Schritt vereinbaren (Wer, was, bis wann).','Danken und Dokumentieren.'],st:['Wesentliche Punkte zusammenfassen.','Fragen klären.','Entscheidung erfragen.','Nächsten Schritt festlegen.','Verabschieden.'],g:'„Wir haben heute geklärt, dass Ihnen die Zahnleistung wichtig ist. Wie schätzen Sie den Vorschlag ein? Wollen wir den Antrag vorbereiten oder soll ich Ihnen die Unterlagen schicken und wir sprechen nächste Woche?“',b:'„Dann unterschreiben Sie hier.“',f:['Ohne Zusammenfassung enden.','Keinen Termin festlegen.','Entscheidung erzwingen.'],dia:DLG(['Ich glaube, ich habe alles verstanden.','Gut. Wie schätzen Sie den Vorschlag ein?','Ich möchte noch mit meiner Frau reden.','Verständlich. Ich schicke Ihnen die Unterlagen. Soll ich Donnerstag anrufen oder schreiben Sie mir?']),m:['Zusammenfassen, entscheiden, nächster Schritt.','Kein Gespräch ohne Zusage zum Weiteren.'],u:'Schreibe einen Abschlussdialog für ein Gespräch ohne Entscheidung in vier Sätzen.',kw:'abschluss nächste schritte entscheidung folgetermin'});
U('i2','I','Entscheidungen erleichtern, ohne zu drängen',{s:'Entscheidungen fallen leichter, wenn Auswahl überschaubar, Nutzen klar und Risiko verständlich ist. Zu viele Optionen können die Entscheidung erschweren, der Effekt ist aber nicht in allen Studien gleich stark.',w:'Wer überfordert ist, verschiebt. Klarheit hilft dem Kunden.',r:['Zwei bis drei Optionen zeigen.','Empfehlung begründen.','Entscheidung dem Kunden überlassen.','Sicherheit schaffen, nicht Druck.'],g:'„Aus Ihrer Sicht passen zwei Varianten. Ich würde die erste empfehlen, weil Zahn Ihnen wichtig ist. Welche spricht Sie mehr an?“',b:'„Das Angebot gilt nur heute.“',f:['Zu viele Varianten.','Künstliche Frist.'],m:['Wenige Optionen, klare Empfehlung.','Entscheidung gehört dem Kunden.'],u:'Reduziere eine Auswahl von fünf Tarifen auf zwei Varianten mit Begründung.',q:['il','sg'],typ:'beleg',kw:'entscheidung erleichtern auswahl optionen'});
L('i3','I','Abschlusssignale erkennen','Signale: Fragen zum Ablauf, Wiederholen von Vorteilen, Nachfrage zu Beginn. Auch hier gilt: nachfragen.',['Signal beschreiben.','Prüfen, ob der Kunde bereit ist.','Nicht überinterpretieren.'],['Signal ist keine Zusage.']);
L('i4','I','Abschlussfragen','Abschlussfragen sind klar und ohne Druck: „Wie möchten Sie vorgehen?“',['Offen formulieren.','Alternativen zulassen.','Pause lassen.'],['Klar fragen, Zeit lassen.']);
L('i5','I','Nächste Schritte vereinbaren','Wer macht was bis wann? Das wird mündlich und schriftlich festgehalten.',['Konkretes Datum.','Verantwortlichkeit nennen.','Kurz per Nachricht bestätigen.'],['Wer, was, bis wann.']);
L('i6','I','Folgetermin sichern','Der Folgetermin wird im Gespräch vereinbart, nicht danach.',['Vorschlag machen.','Kalender gemeinsam ansehen.','Erinnerung anbieten.'],['Termin im Gespräch.']);
L('i7','I','Wenn der Kunde nicht entscheiden möchte','Das ist okay. Offene Fragen klären, Frist anbieten, Kontakt vereinbaren.',['Ruhig bleiben.','Fragen klären.','Kontakt vereinbaren.'],['Nicht entscheiden ist auch eine Entscheidung.']);
L('i8','I','Dokumentation des Gesprächs','Beratung und Gründe der Empfehlung müssen dokumentiert werden (§ 61 VVG). Unterlagen und Kundenwunsch festhalten.',['Zeitnah dokumentieren.','Kundenwünsche in Kundenworten.','Empfehlung begründen.'],['Dokumentation ist Pflicht und Schutz.']);
/* ---------- J Kommunikation ---------- */
U('j1','J','Verständlich sprechen',{s:'Verständlich sprechen heißt kurze Sätze, klare Wörter, passendes Tempo und Pausen.',w:'Kunden hören nur so lange zu, wie sie folgen können.',r:['Kurze Sätze.','Ein Gedanke pro Satz.','Tempo senken bei Zahlen.','Pausen nach Kernaussagen.'],g:'„Die Kasse zahlt einen Teil. Den Rest zahlen Sie. Dafür gibt es die Zusatzversicherung.“',b:'„Im Falle einer leistungsrechtlich relevanten Konstellation …“',f:['Schachtelsätze.','Floskeln.'],m:['Kurz, klar, langsam.'],u:'Formuliere einen Absatz aus Fachsprache in Alltagssprache um.',kw:'verständlich sprechen stimme tempo'});
U('j2','J','Nervosität im Gespräch',{s:'Nervosität ist normal. Vorbereitung, Atmung und ein klarer Anfang helfen.',w:'Ruhe überträgt sich auf den Kunden.',r:['Vorbereitet sein.','Langsam atmen vor dem Termin.','Ersten Satz sicher haben.','Nicht entschuldigen.'],g:'Dreimal tief ein- und ausatmen, dann die Begrüßung.',b:'Hektisch zu starten und sich zu entschuldigen.',f:['Zu schnell reden.','Nervosität verstecken wollen.'],m:['Ruhe lässt sich üben.'],u:'Schreibe dein persönliches Ritual vor einem Gespräch auf.',kw:'nervosität aufregung ruhe atmung'});
L('j3','J','Körpersprache bewusst einsetzen','Offene Haltung, ruhige Hände, Blickkontakt. Wirkung nicht überschätzen, Inhalt zählt.',['Zugewandt sitzen.','Hände sichtbar.','Nicht überdeuten.'],['Körpersprache unterstützt.']);
L('j4','J','Mimik und Blickkontakt','Freundliche Mimik und Blickkontakt ohne Starren schaffen Kontakt.',['Blick halten, auch lösen.','Lächeln, wenn es passt.','Notizen mit Ankündigung.'],['Echt wirken.']);
L('j5','J','Stimme, Betonung und Pausen','Betonung hebt Wichtiges hervor, Pausen geben Zeit.',['Wichtiges betonen.','Pausen setzen.','Monotonie vermeiden.'],['Pause vor und nach dem Wichtigen.']);
L('j6','J','Sprache in Telefonaten','Am Telefon zählt Stimme: klar, freundlich, strukturiert. Zusammenfassen häufiger.',['Vorbereitet anrufen.','Kurz begrüßen.','Ziel nennen.'],['Telefon: Stimme und Struktur.']);
L('j7','J','Schriftliche Nachrichten','Kurz, klar, mit nächstem Schritt. Keine Kundendaten in unsicheren Kanälen.',['Betreff klar.','Eine Bitte pro Nachricht.','Datenschutz beachten.'],['Kurz und konkret.']);
L('j8','J','Umgang mit Emotionen','Emotionen des Kunden anerkennen, ruhig bleiben, danach zur Sache.',['Gefühl benennen.','Ruhig bleiben.','Pause anbieten.'],['Erst Gefühl, dann Sache.']);
/* ---------- K Psychologie ---------- */
U('k1','K','Wie Menschen Entscheidungen treffen',{s:'Menschen entscheiden nicht rein rational. Die Prospect Theory (Kahneman & Tversky 1979) beschreibt, dass Verluste stärker gewichtet werden als gleich große Gewinne. Das ist ein Modell, kein Vertriebsinstrument.',w:'Wer versteht, wie Entscheidungen entstehen, kann besser unterstützen. Dieses Wissen darf nicht zur Manipulation genutzt werden.',r:['Verluste wiegen für viele schwerer als Gewinne (Verlustaversion).','Menschen bleiben gern beim Gewohnten (Status-quo-Effekt, Samuelson & Zeckhauser 1988).','Zu viele Optionen können Entscheidungen erschweren, die Befunde sind gemischt (Iyengar & Lepper 2000; Scheibehenne et al. 2010).','Wissen über Entscheidungsverhalten ist ein Grund für klare Beratung, nicht für Druck.'],g:'„Wir haben zwei Varianten. Was ist Ihnen wichtiger?“',b:'„Sie verlieren alles, wenn Sie nicht abschließen.“',f:['Verlustangst als Druck nutzen.','Studien ohne Einordnung zitieren.'],m:['Psychologie erklärt, rechtfertigt aber keinen Druck.','Studien sind Modelle, keine Gesetze.'],u:'Beschreibe, wie du einem Kunden eine Entscheidung erleichterst, ohne Verlustängste zu nutzen.',q:['kt','sz','il','sg'],typ:'beleg',kw:'psychologie entscheidung verlustaversion status quo auswahl'});
U('k2','K','Ethische Grenzen der Beeinflussung',{s:'Beeinflussung ist ethisch vertretbar, wenn sie transparent ist, dem Interesse des Kunden dient und die freie Entscheidung erhält.',w:'Manipulation verletzt das Vertrauen und kann rechtliche Folgen haben (Beratungspflicht).',r:['Gründe offenlegen.','Keine Angst, kein Zeitdruck als Hebel.','Keine falschen Aussagen.','Kunden Zeit und Alternativen lassen.'],g:'„Das spricht dafür, das dagegen. Sie entscheiden.“',b:'„Nur noch heute zu diesem Preis.“ (wenn nicht wahr)',f:['Künstliche Knappheit.','Falsche Vergleichszahlen.'],m:['Transparenz ist die Grenze.'],u:'Nenne drei Techniken, die du bewusst nicht einsetzen wirst.',q:['vv'],typ:'beleg',kw:'ethik manipulation druck grenzen'});
L('k3','K','Vertrauen und Glaubwürdigkeit','Vertrauen speist sich aus Kompetenz, Wohlwollen, Integrität (Mayer et al. 1995).',['Zusagen einhalten.','Offen sein.','Fachlich vorbereitet.'],['Dreiklang: Können, Wollen, Ehrlich sein.']);
L('k4','K','Verlustaversion verantwortungsvoll einordnen','Verluste wiegen oft stärker als Gewinne. Im Gespräch gilt: Risiken sachlich zeigen, nicht dramatisieren.',['Sachlich bleiben.','Zahlen mit Quelle.','Nicht Angst als Hebel.'],['Risiko sachlich zeigen.']);
L('k5','K','Status-quo-Effekt','Menschen neigen dazu, beim Bestehenden zu bleiben. Das erklärt Zögern bei Wechseln.',['Vorteile und Aufwand zeigen.','Schritte klein halten.','Nicht verurteilen.'],['Zögern hat Gründe.']);
