EINW=KN.filter(function(u){return u.ew}).map(function(u){return u.e});
var wk={mode:'akad',cat:'',unit:'',q:'',s:'',ans:null,busy:false,ex:{},exTxt:{},more:{},favOnly:false};
var wkFavMem=null;
