function wkEx(u){
  var st=wk.ex[u.id]||{},prompt=u.ew?'Der Kunde sagt: „'+u.e+'“. Wie antwortest du?':(u.u||'');
  if(!prompt)return '';
  var h='<section class="wks wkex"><h4>Übung</h4><p>'+esc(prompt)+'</p><label for="wk-ex" class="sr">Deine Antwort</label><textarea id="wk-ex" rows="4" maxlength="1200" data-wk="ex" data-id="'+u.id+'" placeholder="Deine Antwort oder Formulierung">'+esc(wk.exTxt[u.id]||'')+'</textarea><div class="btnrow"><button class="btn primary" data-act="wk-ex" data-id="'+u.id+'"'+(st.busy?' disabled':'')+'>'+(st.busy?'Wird bewertet ...':'Rückmeldung holen')+'</button></div>';
  if(st.err)h+='<p class="err" role="alert">'+esc(st.err)+'</p>';
  if(st.res){var r=st.res;h+='<div class="nbp" style="margin-top:12px"><div class="nbr"><span><b>Was gut war</b><small>'+esc(r.gut)+'</small></span></div><div class="nbr"><span><b>Was du verbessern kannst</b><small>'+esc(r.besser)+'</small></span></div><div class="nbr"><span><b>Alternative Formulierung</b><small style="font-size:14.5px;color:var(--ink)">'+esc(r.alt)+'</small></span></div><div class="nbr"><span><b>Warum das besser wirkt</b><small>'+esc(r.warum)+'</small></span></div></div><p class="hint-t">'+(r.src==='ki'?'Rückmeldung von Claude.':'Einfache Regelprüfung auf deinem Gerät, keine KI. Sie erkennt nur Merkmale wie Rückfrage, Verständnis und Druck.')+'</p>'}
  return h+'</section>';
}
function wkUnit(id){
  var u=KN_IDX[id];if(!u)return wkHome();
  var c=knCat(u.c),fav=wkFav().indexOf(id)>=0,more=!!wk.more[id];
  var h='<div class="plbar"><button class="linkbtn" data-act="wk-cat" data-id="'+c.id+'">← '+esc(c.t)+'</button><button class="linkbtn" data-act="wk-home">Alle Bereiche</button></div>';
  h+='<div class="wkhead" style="--hc:'+c.col+'"><div><small>'+c.id+'  '+esc(c.t)+(u.typ==='beleg'?' · mit Quellen':u.typ==='modell'?' · Modell':u.light?' · Kurzfassung':'')+'</small><h2>'+esc(u.t)+'</h2></div><button class="wkfav" data-act="wk-fav" data-id="'+id+'" aria-pressed="'+fav+'" aria-label="'+(fav?'Favorit entfernen':'Als Favorit merken')+'">'+(fav?'★':'☆')+'</button></div>';
  if(u.ew){
    h+=wkSec('Mögliche Bedeutung',esc(u.bed),'')+wkSec('Nicht vorschnell urteilen',esc(u.nv),'')+wkSec('Gute Rückfrage','<p class="wkq">'+esc(u.rf)+'</p>','wkhl')+wkSec('Mögliche Antwort','<p class="wkq">'+esc(u.aw)+'</p>','wkhl')+wkSec('Konkretes Gesprächsbeispiel',wkDia(u.dia),'')+wkSec('Typischer Fehler',esc(u.fe),'')+wkSec('Lernpunkt','<div class="wkmerk"><p>'+esc(u.lp)+'</p></div>','')+wkEx(u);
    h+='<p class="hint-t">Hinweis: Die Formulierungen sind Beispiele und müssen zu deiner Person und zum Kunden passen. Fiktives Beispiel, keine echten Kunden.</p>';
    return h+'<div class="plbar" style="margin-top:12px"><button class="btn small" data-act="wk-go" data-id="training">Im Training üben</button></div>';
  }
  if(u.prod){
    h+=wkSec('Kurz erklärt',esc(u.s),'')+wkSec('Für wen relevant',esc(u.fur),'')+wkSec('Nutzen',esc(u.nutzen),'')+wkSec('Grenzen und Vorsicht',esc(u.gren),'')+wkSec('Fragen für das Gespräch',wkUl(u.frag),'wkhl')+
      wkSec('Typische Einwände','<div class="wkl">'+(u.eid||[]).map(function(i){var e=KN_IDX[i];return e?'<button class="wkli" data-act="wk-unit" data-id="'+i+'" style="--hc:#B4506B"><b>'+esc(e.t)+'</b></button>':''}).join('')+'</div>','')+
      wkSec('Allgemeines Wissen oder konkrete Tarifinfo?','<p>'+esc(u.tarif)+'</p><p class="hint-t">Diese Seite enthält allgemeines Wissen. Konkrete Tarife, Beiträge, aktuelle Zahlen und Bedingungen müssen in den aktuellen Unterlagen geprüft werden.</p>','wkwarn')+wkSrc(u);
    return h+'<div class="plbar" style="margin-top:12px"><button class="btn small primary" data-act="wk-go" data-id="vorbereitung">Gespräch vorbereiten</button><button class="btn small" data-act="wk-askunit" data-id="'+id+'">KI zu diesem Thema fragen</button></div>';
  }
  if(u.light){
    h+=wkSec('Kurz erklärt',esc(u.s),'')+wkSec('Wichtigste Regeln',wkUl(u.r),'')+wkSec('Merksatz',wkMerk(u),'');
    h+='<p class="hint-t">Kurzfassung. Eine ausführliche Lerneinheit mit Beispielen, Dialog und Übung gibt es für dieses Thema noch nicht. Du kannst die KI bitten, es zu vertiefen.</p><div class="plbar"><button class="btn small" data-act="wk-askunit" data-id="'+id+'">KI: Thema vertiefen</button></div>';
    return h;
  }
  h+=wkSec('Kurz erklärt',esc(u.s),'wkhl')+(u.m&&u.m.length?wkSec('Merksätze',wkMerk(u),''):'');
  if(!more)h+='<div class="plbar"><button class="btn" data-act="wk-more" data-id="'+id+'">Mehr anzeigen</button></div>';
  else{
    h+=wkSec('Warum wichtig',esc(u.w),'')+wkSec('Wichtigste Regeln',wkUl(u.r),'')+wkSec('So machst du es',wkOl(u.st),'');
    if(u.g||u.b)h+=wkSec('Beispiele','<div class="wkgb">'+(u.g?'<div class="wkg"><small>Besser</small>'+esc(u.g)+'</div>':'')+(u.b?'<div class="wkb"><small>Weniger gut</small>'+esc(u.b)+'</div>':'')+'</div>','');
    h+=wkSec('Typische Fehler',wkUl(u.f),'')+wkSec('Praxisdialog',wkDia(u.dia),'')+wkEx(u)+wkSrc(u);
    h+='<div class="plbar"><button class="btn small" data-act="wk-more" data-id="'+id+'">Weniger anzeigen</button><button class="btn small" data-act="wk-askunit" data-id="'+id+'">KI: Frage dazu</button></div>';
  }
  return h;
}
function viewAkademie(){
  var h=wissenSeg('akademie');
  return h+(wk.unit?wkUnit(wk.unit):wk.cat?wkList(wk.cat):wkHome());
}
/* lokale Rückmeldung ohne KI */
function exLocal(txt,u){
  var t=String(txt||''),L=t.toLowerCase(),gut=[],bes=[];
  var q=/\?/.test(t),emp=/(verstehe|verständlich|nachvollzieh|danke|gern|gute idee|tut mir leid)/.test(L),pr=/(nur heute|unbedingt|müssen sie|sofort|letzte chance|sonst)/.test(L),nxt=/(termin|nächste|melde|schicke|woche|bis |gebe ihnen)/.test(L),nut=/(das heißt|das bedeutet|für sie|ihnen wichtig|ihre situation)/.test(L),long=t.length>400,short=t.length<40;
  if(emp)gut.push('Du zeigst Verständnis.');if(q)gut.push('Du stellst eine Rückfrage.');if(nxt)gut.push('Du nennst einen nächsten Schritt.');if(nut)gut.push('Du verbindest die Antwort mit der Situation des Kunden.');
  if(!gut.length)gut.push('Du hast eine Antwort formuliert, das ist der erste Schritt.');
  if(!emp)bes.push('Beginne mit einem Satz, der zeigt, dass du den Einwand verstanden hast.');
  if(!q)bes.push('Stelle eine offene Rückfrage, damit du den Hintergrund erfährst.');
  if(!nxt)bes.push('Schließe mit einem konkreten nächsten Schritt ab.');
  if(pr)bes.push('Streiche Druckformulierungen wie „nur heute“ oder „unbedingt“.');
  if(long)bes.push('Kürze die Antwort auf zwei bis drei Sätze.');
  if(short)bes.push('Erkläre etwas mehr, damit der Kunde dich versteht.');
  if(!bes.length)bes.push('Prüfe, ob du Nutzen und Grenzen ehrlich benennst.');
  var alt=u&&u.aw?u.aw:u&&u.g?u.g:'Verstehe. Was genau ist Ihnen dabei wichtig? Dann schauen wir gemeinsam, was dazu passt.';
  var warum=u&&u.lp?u.lp:u&&u.m&&u.m[0]?u.m[0]:'Verständnis und Rückfrage nehmen Druck aus dem Gespräch und zeigen dem Kunden, dass er ernst genommen wird.';
  return {gut:gut.join(' '),besser:bes.slice(0,3).join(' '),alt:alt,warum:warum,src:'lokal'};
}
function exRun(id){
  var u=KN_IDX[id],st=wk.ex[id]||(wk.ex[id]={});if(st.busy)return;
  var a=(wk.exTxt[id]||'').trim();st.err='';
  if(!a){st.err='Bitte zuerst eine Antwort eintragen.';render();return}
  var e=checkText(a);if(e){st.err=e;render();return}
  st.busy=true;st.res=null;render();
  getSample(function(sample){
    if(!sample){st.busy=false;st.res=exLocal(a,u);render();return}
    var aufg=u.ew?'Der Kunde sagt: „'+u.e+'“.':'Aufgabe: '+(u.u||'');
    var pr='Du bist Verkaufstrainer für einen Versicherungsvertreter (R&V, Volksbank, Deutschland). Thema der Lerneinheit: '+u.t+'. '+aufg+' Der Berater antwortet: „'+a+'“. Bewerte fair und konkret, ohne manipulative Methoden zu empfehlen. Antworte NUR als JSON: {"gut":"1 bis 2 Sätze, was gut war","besser":"1 bis 2 Sätze, was konkret besser geht","alt":"eine alternative Formulierung in 2 bis 3 Sätzen","warum":"1 Satz, warum diese Alternative besser wirkt"}. Keine Floskeln, keine Namen.';
    sample.json(pr,{modelTier:'quick',cache:false}).then(function(r){
      st.busy=false;st.res={gut:String(r&&r.gut||'').slice(0,400),besser:String(r&&r.besser||'').slice(0,500),alt:String(r&&r.alt||'').slice(0,600),warum:String(r&&r.warum||'').slice(0,400),src:'ki'};if(!st.res.gut&&!st.res.alt)st.res=exLocal(a,u);render();
    },function(er){st.busy=false;st.res=exLocal(a,u);st.err=chErr(er);render()});
  });
}
/* Umschaltung zwischen den Wissensbereichen (Lexikon, Akademie, Wissens-Chat) */
function wissenSeg(akt){
  return '<div class="seg wseg" role="group" aria-label="Wissensbereich">'+[['wissen','Lexikon'],['akademie','Vertriebsakademie'],['wissenki','Wissens-Chat']].map(function(x){return '<button data-act="tab" data-tab="'+x[0]+'" aria-pressed="'+(akt===x[0])+'">'+x[1]+'</button>'}).join('')+'</div>';
}
